class InvalidMarkException extends Exception {
    private static final long serialVersionUID = 1L;
    InvalidMarkException(String message) { super(message); }
}

class Main {
    static void accept(int mark) throws InvalidMarkException {
        if (mark < 0 || mark > 100) { throw new InvalidMarkException("Mark outside 0..100"); }
    }
    public static void main(String[] args) throws Exception {
        try {
            accept(101);
        } catch (InvalidMarkException problem) {
            System.out.println(problem.getMessage());
        }
    }
}

class Gate implements AutoCloseable {
    void open() { System.out.println("Opened"); }
    @Override
    public void close() { throw new IllegalStateException("close"); }
}

class Main {
    public static void main(String[] args) throws Exception {
        try (Gate gate = new Gate()) {
            gate.open();
            throw new IllegalStateException("body");
        } catch (IllegalStateException problem) {
            System.out.println(problem.getMessage());
            System.out.println(problem.getSuppressed()[0].getMessage());
        }
    }
}
